// This file's job is to deal with the update_server and network side
// of the updater library.

use serde::{Deserialize, Deserializer, Serialize, Serializer};

use crate::{
    config::{current_arch, current_platform, UpdateConfig},
    time,
};

#[derive(Debug, Clone, PartialEq)]
#[allow(clippy::enum_variant_names)] // Prefix matches the domain concept, not a naming mistake.
pub enum EventType {
    PatchInstallSuccess,
    PatchInstallFailure,
    PatchDownload,
    PatchUpdateFailure,
    /// A NON-TERMINAL boot-lifecycle observation.
    ///
    /// Deliberately NOT `PatchInstallFailure`. A first ambiguous unfinished boot
    /// is not evidence that the patch or its installation failed, and reporting
    /// it under a failure type would assert exactly what the state machine
    /// refuses to assert — as well as corrupting existing failure metrics.
    PatchBootLifecycle,
}

/// What a [`EventType::PatchBootLifecycle`] event observed.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum BootOutcome {
    /// A boot did not finish; below threshold, so the patch was RETRIED.
    /// Evidence about the boot, NOT about the patch.
    AmbiguousBootRetry,
    /// A patch booted successfully after prior ambiguity. This is the
    /// population that justifies having a threshold at all, and the one the
    /// server could never see while only terminal outcomes were reported.
    RecoveredAfterAmbiguity,
    /// Ambiguity reached the threshold and the patch was retired.
    RetiredAfterAmbiguity,
}

impl Serialize for EventType {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        serializer.serialize_str(match self {
            EventType::PatchInstallSuccess => "__patch_install__",
            EventType::PatchInstallFailure => "__patch_install_failure__",
            EventType::PatchDownload => "__patch_download__",
            EventType::PatchUpdateFailure => "__patch_update_failure__",
            EventType::PatchBootLifecycle => "__patch_boot_lifecycle__",
        })
    }
}

impl<'de> Deserialize<'de> for EventType {
    fn deserialize<D>(deserializer: D) -> Result<EventType, D::Error>
    where
        D: Deserializer<'de>,
    {
        let s = String::deserialize(deserializer)?;
        match s.as_str() {
            "__patch_install__" => Ok(EventType::PatchInstallSuccess),
            "__patch_install_failure__" => Ok(EventType::PatchInstallFailure),
            "__patch_download__" => Ok(EventType::PatchDownload),
            "__patch_update_failure__" => Ok(EventType::PatchUpdateFailure),
            "__patch_boot_lifecycle__" => Ok(EventType::PatchBootLifecycle),
            _ => Err(serde::de::Error::custom(format!("Unknown event type: {s}"))),
        }
    }
}

/// An event sent to the server about a patch: a download, an install, or an
/// install or update failure.
///
/// Any edits to this struct should be made carefully and in accordance
/// with our privacy policy, <https://shorebird.dev/privacy/>, and should
/// keep the list of what Shorebird collects up to date:
/// <https://docs.shorebird.dev/system/what-shorebird-collects/>
#[derive(Debug, Serialize, Deserialize, Clone, PartialEq)]
pub struct PatchEvent {
    /// The Shorebird app_id built into the shorebird.yaml in the app.
    pub app_id: String,

    /// The architecture we're running (e.g. "aarch64", "x86", "x86_64").
    pub arch: String,

    /// The anonymous install identifier. A random UUID generated by Shorebird,
    /// per install rather than per device.
    pub client_id: String,

    /// The identifier of this event.
    #[serde(rename = "type")]
    pub identifier: EventType,

    /// The patch number that was installed.
    pub patch_number: usize,

    /// The platform we're running on (e.g. "android", "ios", "windows", "macos", "linux").
    pub platform: String,

    /// The release version from AndroidManifest.xml, Info.plist in the app.
    pub release_version: String,

    /// When this event occurred as a Unix epoch timestamp in seconds.
    pub timestamp: u64,

    /// An optional message to be sent with the event.
    /// Care should be taken that this field *never* contain PII or sensitive information.
    pub message: Option<String>,

    /// For failure events, a stable, low-cardinality classification of the
    /// failure (the `FailureCategory` code, e.g. "network", "corrupt_patch").
    /// Sent as structured data so the server does not have to parse it back out
    /// of `message`. Optional and ignored by servers that don't yet read it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub failure_category: Option<String>,

    /// A random UUID made when the event is created, so the server can count
    /// an event the device sent more than once (a retry after a lost
    /// response) only once. `None` only for events queued by an updater
    /// that predates it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub event_id: Option<String>,

    /// The updater revision that produced this event. Not PII: it identifies the
    /// CLIENT CODE, not the device or user.
    ///
    /// Sent on EVERY event type, deliberately. Eligibility for policy analysis is a
    /// property of the behaviour-bearing client code — whether it shipped the
    /// event-loss fixes — and inferring that from an app release version is a proxy
    /// that only works for one app. `"unknown"` when the build could not determine
    /// it, which the server must treat as pre-epoch rather than trusting.
    ///
    /// `#[serde(default)]` (a port change): events already queued in a
    /// `state.json` written by an updater without this field must still
    /// deserialize, or one old queued event would make the whole state
    /// unreadable after an upgrade.
    #[serde(default = "unknown_updater_revision")]
    pub updater_revision: String,

    // ---- Boot-lifecycle fields ----
    //
    // All optional and skipped when absent, so every pre-existing event type
    // serialises BYTE-IDENTICALLY and the server's dedupe key is unperturbed.
    //
    // No new correlation identifier is introduced: the envelope already carries
    // `client_id`, `app_id`, `release_version` and `patch_number`, and
    // (app_id, release_version) uniquely identifies a release server-side while
    // patch numbers are unique only WITHIN a release. Timestamps are ordering
    // and evidence, never identity.
    /// What was observed. `None` for every non-lifecycle event.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub outcome: Option<BootOutcome>,

    /// Un-succeeded boots of this patch counted so far. On a recovery this is
    /// the ambiguity that PRECEDED the success, captured before it was cleared.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub ambiguous_attempt_count: Option<u32>,

    /// The threshold in force on the device, so fleet data stays interpretable
    /// if the shipped value ever changes.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub boot_failure_threshold: Option<u32>,

    /// When the observed boot began. Retained even though policy currently
    /// IGNORES boot age, so it can later be determined whether a 40ms
    /// unfinished boot and a 40-day stale breadcrumb are the same population —
    /// before any age rule is introduced.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub boot_started_at: Option<u64>,
}

fn unknown_updater_revision() -> String {
    "unknown".to_string()
}

impl PatchEvent {
    /// Creates a `PatchEvent` for the given `EventType` and patch number for reporting to the server.
    pub fn new(
        config: &UpdateConfig,
        event_type: EventType,
        patch_number: usize,
        client_id: String,
        message: Option<&str>,
    ) -> PatchEvent {
        PatchEvent {
            app_id: config.app_id.clone(),
            arch: current_arch().to_string(),
            client_id,
            identifier: event_type,
            patch_number,
            platform: current_platform().to_string(),
            release_version: config.release_version.clone(),
            timestamp: time::unix_timestamp(),
            message: message.map(|s| s.to_string()),
            failure_category: None,
            event_id: Some(uuid::Uuid::new_v4().to_string()),
            updater_revision: env!("UPDATER_REVISION").to_string(),
            outcome: None,
            ambiguous_attempt_count: None,
            boot_failure_threshold: None,
            boot_started_at: None,
        }
    }

    /// Builds a non-terminal boot-lifecycle observation.
    pub fn boot_lifecycle(
        config: &UpdateConfig,
        patch_number: usize,
        client_id: String,
        outcome: BootOutcome,
        ambiguous_attempt_count: u32,
        boot_failure_threshold: u32,
        boot_started_at: Option<u64>,
    ) -> PatchEvent {
        PatchEvent {
            outcome: Some(outcome),
            ambiguous_attempt_count: Some(ambiguous_attempt_count),
            boot_failure_threshold: Some(boot_failure_threshold),
            boot_started_at,
            ..PatchEvent::new(
                config,
                EventType::PatchBootLifecycle,
                patch_number,
                client_id,
                None,
            )
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn event_type_round_trips() {
        let types = [
            (EventType::PatchInstallSuccess, "__patch_install__"),
            (EventType::PatchInstallFailure, "__patch_install_failure__"),
            (EventType::PatchDownload, "__patch_download__"),
            (EventType::PatchUpdateFailure, "__patch_update_failure__"),
        ];
        for (event_type, expected_str) in &types {
            let json = serde_json::to_string(event_type).unwrap();
            assert_eq!(json, format!("\"{expected_str}\""));
            let deserialized: EventType = serde_json::from_str(&json).unwrap();
            assert_eq!(&deserialized, event_type);
        }
    }

    #[test]
    fn event_without_id_deserializes() {
        let json = r#"{"app_id":"a","arch":"aarch64","client_id":"c",
            "type":"__patch_install_failure__","patch_number":1,
            "platform":"android","release_version":"1.0.0","timestamp":1,
            "message":null}"#;
        let event: PatchEvent = serde_json::from_str(json).unwrap();
        assert_eq!(event.event_id, None);
        assert!(serde_json::to_value(&event)
            .unwrap()
            .get("event_id")
            .is_none());
    }

    #[test]
    fn unknown_event_type_fails_deserialization() {
        let result = serde_json::from_str::<EventType>("\"__bogus__\"");
        assert!(result.is_err());
        let err = result.unwrap_err().to_string();
        assert!(
            err.contains("Unknown event type"),
            "unexpected error: {err}"
        );
    }
}
